import json
from pathlib import Path
L=[]
def a(w,r,m,pos,u,j,k,ro,e,n):L.append(dict(word=w,reading=r,romaji='',meaning=m,pos=pos,usage=u,example=j,example_reading=k,example_romaji=ro,translation=e,nuance=n))
a('嬉しい','うれしい','happy; pleased','い-adjective','知らせが嬉しい','合格の知らせを聞いて、嬉しかった。','ごうかくのしらせをきいて、うれしかった。','Goukaku no shirase o kiite, ureshikatta.','I was happy to hear that I had passed.','A pleased reaction to an event; 楽しい describes enjoying an activity.')
a('悲しい','かなしい','sad','い-adjective','悲しい知らせ','友達が遠くへ引っ越すので、悲しいです。','ともだちがとおくへひっこすので、かなしいです。','Tomodachi ga tooku e hikkosu node, kanashii desu.','I am sad because my friend is moving far away.','Describes sadness; 寂しい focuses on loneliness or missing someone.')
a('楽しい','たのしい','enjoyable; fun','い-adjective','楽しい時間を過ごす','みんなで料理を作るのは楽しい。','みんなでりょうりをつくるのはたのしい。','Minna de ryouri o tsukuru no wa tanoshii.','Cooking together is fun.','An enjoyable experience, unlike 嬉しい as a pleased response to news.')
a('寂しい','さびしい','lonely; miss someone','い-adjective','一人で寂しい','家族と離れて暮らすのは寂しいです。','かぞくとはなれてくらすのはさびしいです。','Kazoku to hanarete kurasu no wa sabishii desu.','Living away from my family feels lonely.','さみしい is also common; learn the written form with either reading.')
a('怖い','こわい','frightening; afraid','い-adjective','犬が怖い','子どものころは、大きな犬が怖かった。','こどものころは、おおきないぬがこわかった。','Kodomo no koro wa, ookina inu ga kowakatta.','As a child, I was afraid of large dogs.','The frightening object is often marked が, not を.')
a('驚く','おどろく','be surprised','godan intransitive verb','知らせに驚く','急に名前を呼ばれて驚いた。','きゅうになまえをよばれておどろいた。','Kyuu ni namae o yobarete odoroita.','I was surprised when my name was suddenly called.','Use に for the cause of surprise; 驚かす means surprise someone.')
a('安心','あんしん','relief; peace of mind','noun/suru; na-adjective','無事だと聞いて安心する','友達が無事だと分かって安心しました。','ともだちがぶじだとわかってあんしんしました。','Tomodachi ga buji da to wakatte anshin shimashita.','I felt relieved when I learned my friend was safe.','安全 describes safety itself; 安心 is feeling reassured.')
a('心配','しんぱい','worry; concern','noun/suru; na-adjective','家族を心配する','母は一人で暮らす私を心配しています。','はははひとりでくらすわたしをしんぱいしています。','Haha wa hitori de kurasu watashi o shinpai shite imasu.','My mother worries about me living alone.','Often has a specific object of concern; 不安 can be more general unease.')
a('不安','ふあん','anxiety; uneasiness','noun; na-adjective','将来が不安だ','初めての仕事なので、少し不安です。','はじめてのしごとなので、すこしふあんです。','Hajimete no shigoto na node, sukoshi fuan desu.','It is my first job, so I feel a little anxious.','Use 不安な before a noun and 不安に感じる for feeling anxious.')
a('緊張','きんちょう','nervous tension','noun/suru','人前で緊張する','人前で話すと、今でも緊張します。','ひとまえではなすと、いまでもきんちょうします。','Hitomae de hanasu to, ima demo kinchou shimasu.','I still get nervous when speaking in front of people.','Also describes physical or diplomatic tension; the example is performance anxiety.')
a('恥ずかしい','はずかしい','embarrassed; embarrassing','い-adjective','間違えて恥ずかしい','みんなの前で名前を間違えて、恥ずかしかった。','みんなのまえでなまえをまちがえて、はずかしかった。','Minna no mae de namae o machigaete, hazukashikatta.','I was embarrassed after getting the name wrong in front of everyone.','Another person showing embarrassment can be described with 恥ずかしがる.')
a('残念','ざんねん','disappointing; regrettable','noun; na-adjective','残念な結果','旅行が中止になって残念です。','りょこうがちゅうしになってざんねんです。','Ryokou ga chuushi ni natte zannen desu.','I am disappointed that the trip was canceled.','Often reacts to an unfortunate outcome; not equivalent to apologizing for one’s fault.')
a('悔しい','くやしい','frustrated; bitterly disappointed','い-adjective','負けて悔しい','あと一点で負けたので、とても悔しい。','あといってんでまけたので、とてもくやしい。','Ato itten de maketa node, totemo kuyashii.','I lost by just one point, so I am very frustrated.','Often follows defeat or an outcome that feels unsatisfying; stronger than neutral 残念.')
a('怒る','おこる','get angry','godan intransitive verb','うそをつかれて怒る','約束を破ったので、友達が怒っています。','やくそくをやぶったので、ともだちがおこっています。','Yakusoku o yabutta node, tomodachi ga okotte imasu.','My friend is angry because I broke a promise.','おこる describes anger; the reading いかる is more literary and not prioritized here.')
a('困る','こまる','be troubled; have difficulty','godan intransitive verb','お金に困る / 返事に困る','急に質問されて、返事に困りました。','きゅうにしつもんされて、へんじにこまりました。','Kyuu ni shitsumon sarete, henji ni komarimashita.','Asked a sudden question, I did not know how to respond.','The difficulty takes に; 困らせる means cause someone trouble.')
a('興味','きょうみ','interest','noun','歴史に興味がある','日本の歴史に興味があります。','にほんのれきしにきょうみがあります。','Nihon no rekishi ni kyoumi ga arimasu.','I am interested in Japanese history.','The topic takes に. Do not use 興味する as an ordinary verb.')
a('感動','かんどう','being deeply moved','noun/suru','演奏に感動する','最後の演奏に感動しました。','さいごのえんそうにかんどうしました。','Saigo no ensou ni kandou shimashita.','I was deeply moved by the final performance.','Often an emotional response to art or a meaningful act, not simply surprise.')
a('感謝','かんしゃ','gratitude','noun/suru','人に感謝する','支えてくれた家族に感謝しています。','ささえてくれたかぞくにかんしゃしています。','Sasaete kureta kazoku ni kansha shite imasu.','I am grateful to my family for supporting me.','Use に for the person thanked; ありがとう is the direct everyday expression.')
a('期待','きたい','expectation; hope','noun/suru','人に期待する','新しい店の料理に期待しています。','あたらしいみせのりょうりにきたいしています。','Atarashii mise no ryouri ni kitai shite imasu.','I have high hopes for the food at the new restaurant.','Usually a positive expectation; it is not certainty that something will happen.')
a('希望','きぼう','hope; wish','noun/suru','参加を希望する','午後のクラスへの参加を希望します。','ごごのクラスへのさんかをきぼうします。','Gogo no kurasu e no sanka o kibou shimasu.','I would like to join the afternoon class.','Common on forms for a preferred choice; 期待 anticipates a favorable outcome.')
a('我慢','がまん','endurance; holding back','noun/suru','痛みを我慢する','言いたいことがあったが、我慢しました。','いいたいことがあったが、がまんしました。','Iitai koto ga atta ga, gaman shimashita.','There was something I wanted to say, but I held back.','Can mean enduring discomfort or restraining an impulse; not always a positive recommendation.')
a('不満','ふまん','dissatisfaction','noun; na-adjective','結果に不満がある','説明が足りず、利用者から不満が出た。','せつめいがたりず、りようしゃからふまんがでた。','Setsumei ga tarizu, riyousha kara fuman ga deta.','The explanation was insufficient, and users expressed dissatisfaction.','Contrasts with 満足; 不安 is anxiety rather than dissatisfaction.')
a('喜ぶ','よろこぶ','be delighted; rejoice','godan verb','知らせを喜ぶ','祖母は私の訪問を喜んでくれた。','そぼはわたしのほうもんをよろこんでくれた。','Sobo wa watashi no houmon o yorokonde kureta.','My grandmother was delighted by my visit.','Often describes a reaction or displayed joy; 嬉しい is the adjective describing the feeling.')
a('悲しむ','かなしむ','grieve; feel sorrow for','godan verb','別れを悲しむ','みんなが友達との別れを悲しんだ。','みんながともだちとのわかれをかなしんだ。','Minna ga tomodachi to no wakare o kanashinda.','Everyone was saddened by parting with their friend.','The verb describes grieving or reacting with sadness; 悲しい is the adjective.')
a('落ち着く','おちつく','calm down; settle','godan intransitive verb','気持ちが落ち着く','少し休んだら、気持ちが落ち着きました。','すこしやすんだら、きもちがおちつきました。','Sukoshi yasundara, kimochi ga ochitsukimashita.','After resting a little, I calmed down.','Can describe a settled situation or calm appearance as well as emotion.')
a('落ち込む','おちこむ','feel down; slump','godan intransitive verb','失敗して落ち込む','試験に落ちて、しばらく落ち込んでいました。','しけんにおちて、しばらくおちこんでいました。','Shiken ni ochite, shibaraku ochikonde imashita.','I failed the exam and felt down for a while.','Also describes a numerical slump; the example concerns mood, not a clinical diagnosis.')
a('悩む','なやむ','worry; struggle over a choice','godan intransitive verb','進路に悩む','卒業後の進路に悩んでいます。','そつぎょうごのしんろになやんでいます。','Sotsugyougo no shinro ni nayande imasu.','I am struggling to decide what path to take after graduation.','Often sustained thought over a difficult matter; the issue takes に or について.')
a('気分','きぶん','mood; physical feeling','noun','気分がいい / 悪い','散歩をしたら、気分がよくなりました。','さんぽをしたら、きぶんがよくなりました。','Sanpo o shitara, kibun ga yoku narimashita.','I felt better after taking a walk.','Can refer to bodily condition or mood; 気分が悪い can mean feeling unwell or offended.')
a('勇気','ゆうき','courage','noun','勇気を出す','勇気を出して、先生に質問しました。','ゆうきをだして、せんせいにしつもんしました。','Yuuki o dashite, sensei ni shitsumon shimashita.','I worked up the courage to ask the teacher a question.','Use 勇気がある or 勇気を出す, not 勇気する.')
a('満足','まんぞく','satisfaction','noun/suru; na-adjective','結果に満足する','今回の結果には満足しています。','こんかいのけっかにはまんぞくしています。','Konkai no kekka ni wa manzoku shite imasu.','I am satisfied with this result.','The thing satisfying you takes に; 満腹 specifically means a full stomach.')
def finish(i,title):
 roman='ureshii kanashii tanoshii sabishii kowai odoroku anshin shinpai fuan kinchou hazukashii zannen kuyashii okoru komaru kyoumi kandou kansha kitai kibou gaman fuman yorokobu kanashimu ochitsuku ochikomu nayamu kibun yuuki manzoku'.split()
 for x,r in zip(L,roman):x['romaji']=r
 ex=[dict(type='matching',question='Match 安心 / 不安 / 不満 to relief / anxiety / dissatisfaction.',answer='安心 = relief; 不安 = anxiety; 不満 = dissatisfaction.',explanation='Safety-related reassurance, uncertain unease, and an unsatisfactory outcome are different feelings.'),dict(type='particle',question='歴史（に / を / が / で）興味があります。',options=['に','を','が','で'],answer='に',explanation='The topic of interest takes に.'),dict(type='reading',question='Read 悔しい and 感謝.',answer='くやしい; かんしゃ.',explanation='Learn each complete word reading.'),dict(type='translation',question='Translate: 少し休んだら、気持ちが落ち着きました。',answer='After resting a little, I calmed down.',explanation='落ち着く describes becoming calm.'),dict(type='error correction',question='Correct: 今回の結果を満足しています。',answer='今回の結果に満足しています。',explanation='満足する uses に for what one is satisfied with.'),dict(type='production',question='Say you are grateful to your family, using 感謝.',answer='家族に感謝しています。',explanation='The person receiving gratitude takes に.')]
 Path(__file__).with_name(f'vocab_{i:02d}.json').write_text(json.dumps(dict(id=i,title=title,overview='Distinguish feelings, reactions, and expectations through specific situations.',items=L,exercises=ex),ensure_ascii=False,indent=2),encoding='utf-8')
finish(15,'Feelings and emotional reactions')
